WITH UserBadges AS (SELECT u.Id AS UserId, u.DisplayName, COUNT(b.Id) AS BadgeCount, GROUP_CONCAT(b.Name, ', ') AS BadgeNames FROM Users AS u LEFT JOIN Badges AS b ON u.Id = b.UserId GROUP BY u.Id, u.DisplayName), PostViews AS (SELECT p.OwnerUserId, SUM(p.ViewCount) AS TotalViews, COUNT(p.Id) AS PostCount FROM Posts AS p WHERE p.CreationDate >= CURRENT_DATE() - INTERVAL '1' YEAR GROUP BY p.OwnerUserId), TopAnswerers AS (SELECT p.OwnerUserId, COUNT(p.Id) AS AnswerCount FROM Posts AS p WHERE p.PostTypeId = 2 AND NOT (p.AcceptedAnswerId IS NULL) GROUP BY p.OwnerUserId) SELECT u.DisplayName, ub.BadgeCount, ub.BadgeNames, pv.TotalViews, pv.PostCount, COALESCE(ta.AnswerCount, 0) AS AcceptedAnswerCount, CASE WHEN ub.BadgeCount > 5 THEN 'Veteran' WHEN ub.BadgeCount BETWEEN 3 AND 5 THEN 'Experienced' ELSE 'Novice' END AS UserRank FROM Users AS u LEFT JOIN UserBadges AS ub ON u.Id = ub.UserId LEFT JOIN PostViews AS pv ON u.Id = pv.OwnerUserId LEFT JOIN TopAnswerers AS ta ON u.Id = ta.OwnerUserId WHERE u.Reputation > 1000 ORDER BY UserRank DESC NULLS FIRST, ub.BadgeCount DESC NULLS FIRST, pv.TotalViews DESC NULLS FIRST